  "intended_behavior": "Quantize finite request.speed to signed int32 meters per second. Clamp to the int32 range then truncate toward zero. Observe integer speed_mps, and compare decoded integer speed to the existing strict >30 threshold. Coordinate the incompatible wire change.",
  "change": {
    "id": "telemetry-speed-quantized",
    "category": "field_type_changed",
    "old_schema": "syntax = \"proto3\";\npackage simulation.telemetry;\nmessage VehicleTelemetry {\n  string vehicle_id = 1;\n  // Ground speed in meters per second.\n  float speed_mps = 2;\n}\n",
    "new_schema": "syntax = \"proto3\";\npackage simulation.telemetry;\nmessage VehicleTelemetry {\n  string vehicle_id = 1;\n  // Ground speed truncated to integer meters per second.\n  int32 speed_mps = 2;\n}\n",
    "schema_path": "proto/telemetry/vehicle.proto"
  },
  "file": {
    "path": "runtimes/typescript/telemetry.ts",
    "language": "typescript",
    "source_context": "import { readFileSync } from \"node:fs\";\nimport { VehicleTelemetry } from \"../../generated/ts/telemetry/vehicle\";\n\ninterface Request { payload: string; vehicle_id: string; speed: number }\nexport function runTelemetry() {\n  const requests: Request[] = JSON.parse(readFileSync(0, \"utf8\"));\n  const results = requests.map(request => {\n    const entity = VehicleTelemetry.decode(new Uint8Array(Buffer.from(request.payload, \"base64\")));\n    const sample = VehicleTelemetry.encode({ vehicleId: request.vehicle_id, speedMps: request.speed }).finish();\n    const fields = { vehicle_id: entity.vehicleId, speed_mps: entity.speedMps };\n    return { fields, speeding: entity.speedMps > 30.0, constructed_payload: Buffer.from(sample).toString(\"base64\") };\n  });\n  console.log(JSON.stringify(results));\n}\n"
  },
